select exists (select 1 from pg_proc where pronamespace='public'::regnamespace and proname='is_admin_email') and not (to_regclass('public.student_admin_statuses') is not null) and not (to_regclass('public.student_admin_notes') is not null) and not (to_regclass('public.student_weekly_plans') is not null) and not (to_regclass('public.student_weekly_plan_items') is not null) and not (to_regclass('public.student_activity_events') is not null) as ok;
